import os
import glob
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt
import numpy as np
import re
from scipy.stats import pearsonr
from tqdm import tqdm

# Machine Learning
from sklearn.model_selection import LeaveOneOut
from sklearn.linear_model import RidgeCV
from sklearn.preprocessing import StandardScaler
from sklearn.pipeline import make_pipeline

# --- USER CONFIGURATION ---
BIDS_DIR = "/home/zlow/by84/Brandon/memoria"
BIDS_TASK_NAME = "forgetexp"

# Point to the CSV file generated by your FIRST script
ID_RESULTS_CSV = "./id_analysis_results_by_condition/group_id_full_results_by_condition.csv"

# --- DEFINE WHAT TO LOOP OVER ---
TASK_PHASES_TO_ANALYZE = ["Enc", "Face", "Recall", "Feedback"]
ROIS_TO_ANALYZE = ["V1", "hV4", "LOIT", "phc", "hippocampus"]
BEHAVIORAL_METRICS = ["Accuracy", "Guess_Rate", "Sure_Rate"]

# Output directory for these new results
OUTPUT_DIR = "./id_vs_behavior_comprehensive_correlation_uncorrected"
os.makedirs(OUTPUT_DIR, exist_ok=True)

# Set a p-value threshold for generating individual scatter plots
SIGNIFICANCE_THRESHOLD = 0.05
# --- END OF CONFIGURATION ---


def calculate_behavioral_metrics_for_subject(subject_id, session_id="1"):
    """
    Parses a subject's events.tsv file to calculate overall behavioral metrics FOR RECALL TRIALS.
    """
    try:
        events_file = os.path.join(
            BIDS_DIR, f"sub-{subject_id}", f"ses-{session_id}", "func",
            f"sub-{subject_id}_ses-{session_id}_task-{BIDS_TASK_NAME}_events.tsv"
        )
        df = pd.read_csv(events_file, sep='\t')
    except FileNotFoundError:
        return None

    pattern = re.compile(r'(\w+?)(\d+)_(\w+?)(?:_(\w+))?$')
    parsed_data = df['trial_type'].str.extract(pattern)
    parsed_data.columns = ['Task_Phase', 'ItemID', 'Confidence', 'Accuracy']
    
    recall_df = parsed_data[parsed_data['Task_Phase'] == 'Recall'].copy()
    recall_df = recall_df[recall_df['Confidence'] != 'noResp']
    
    if recall_df.empty: return None
        
    total_trials = len(recall_df)
    
    return {
        "Subject": subject_id,
        "Accuracy": (recall_df['Accuracy'] == 'correct').sum() / total_trials,
        "Guess_Rate": (recall_df['Confidence'] == 'guess').sum() / total_trials,
        "Sure_Rate": (recall_df['Confidence'] == 'sure').sum() / total_trials
    }


def run_comprehensive_correlations(merged_df):
    """
    Runs all correlations and generates heatmaps based on uncorrected p-values.
    """
    print("\n--- Running Analysis 1: Comprehensive Correlations (Uncorrected) ---")
    all_correlations = []
    
    for task_phase in tqdm(TASK_PHASES_TO_ANALYZE, desc="Correlations"):
        for roi in ROIS_TO_ANALYZE:
            for metric in BEHAVIORAL_METRICS:
                subset_df = merged_df[(merged_df['Condition'] == task_phase) & (merged_df['ROI'] == roi)]
                if subset_df.empty: continue
                r_val, p_val = pearsonr(subset_df['Intrinsic_Dim'], subset_df[metric])
                all_correlations.append({
                    "Task_Phase": task_phase, "ROI": roi, "Behavioral_Metric": metric,
                    "r_value": r_val, "p_value": p_val
                })

                if p_val < SIGNIFICANCE_THRESHOLD:
                    print(f"Found significant uncorrected correlation: {task_phase}/{roi} ID vs {metric} (r={r_val:.3f}, p={p_val:.3f})")
                    plt.figure(figsize=(7, 6))
                    sns.regplot(data=subset_df, x='Intrinsic_Dim', y=metric)
                    title = f"{roi} ID during {task_phase} vs. {metric.replace('_', ' ')}\n(r={r_val:.3f}, p={p_val:.3f}, uncorrected)"
                    plt.title(title)
                    plt.xlabel(f"Intrinsic Dimensionality")
                    plt.ylabel(f"Proportion ({metric.replace('_', ' ')})")
                    plt.tight_layout()
                    plot_path = os.path.join(OUTPUT_DIR, f"scatter_{task_phase}_{roi}_{metric}.png")
                    plt.savefig(plot_path, dpi=300)
                    plt.close()

    summary_df = pd.DataFrame(all_correlations)
    summary_path = os.path.join(OUTPUT_DIR, "all_correlations_uncorrected.csv")
    summary_df.to_csv(summary_path, index=False)
    print(f"Full uncorrected correlation summary saved to: {summary_path}")

    # Generate Heatmaps
    for metric in BEHAVIORAL_METRICS:
        metric_df = summary_df[summary_df['Behavioral_Metric'] == metric]
        pivot_r = metric_df.pivot(index="ROI", columns="Task_Phase", values="r_value").reindex(index=ROIS_TO_ANALYZE, columns=TASK_PHASES_TO_ANALYZE)
        pivot_p = metric_df.pivot(index="ROI", columns="Task_Phase", values="p_value").reindex(index=ROIS_TO_ANALYZE, columns=TASK_PHASES_TO_ANALYZE)
        
        annot = pivot_p.applymap(lambda p: "*" if p < SIGNIFICANCE_THRESHOLD else "")

        plt.figure(figsize=(10, 8))
        sns.heatmap(pivot_r, annot=annot, fmt='s', cmap='vlag', center=0, linewidths=.5, cbar_kws={'label': "Pearson's r"})
        plt.title(f"Correlation (r) between ID and {metric.replace('_', ' ')}\n(* indicates p < 0.05, uncorrected)")
        plt.ylabel("Region of Interest (ROI)"); plt.xlabel("Task Phase")
        heatmap_path = os.path.join(OUTPUT_DIR, f"heatmap_uncorrected_correlation_{metric}.png")
        plt.savefig(heatmap_path, dpi=300, bbox_inches='tight')
        plt.close()
        print(f"Heatmap for {metric} saved to: {heatmap_path}")


def run_prediction_analysis(merged_df):
    """
    Runs a multivariate machine learning analysis to predict behavior from ID patterns.
    """
    print("\n--- Running Analysis 2: Multivariate Prediction of Behavior ---")
    
    task_phase_for_prediction = 'Recall'
    behavior_to_predict = 'Guess_Rate'
    
    print(f"Attempting to predict '{behavior_to_predict}' from the pattern of ID across all ROIs during '{task_phase_for_prediction}'.")

    X_df = merged_df[merged_df['Condition'] == task_phase_for_prediction].pivot(
        index='Subject', columns='ROI', values='Intrinsic_Dim'
    )[ROIS_TO_ANALYZE]

    y_df = merged_df[merged_df['Condition'] == task_phase_for_prediction][['Subject', behavior_to_predict]].drop_duplicates().set_index('Subject')
    y = y_df.loc[X_df.index][behavior_to_predict]
    X = X_df.values

    model = make_pipeline(StandardScaler(), RidgeCV(alphas=np.logspace(-3, 3, 100)))
    
    loo = LeaveOneOut()
    predicted_y = np.zeros_like(y)

    for train_index, test_index in loo.split(X):
        X_train, X_test = X[train_index], X[test_index]
        y_train, y_test = y.iloc[train_index], y.iloc[test_index]
        model.fit(X_train, y_train)
        predicted_y[test_index] = model.predict(X_test)
        
    pred_r, pred_p = pearsonr(y, predicted_y)

    print("\n--- Prediction Results ---")
    print(f"Correlation between true and predicted '{behavior_to_predict}':")
    print(f"  Pearson's r = {pred_r:.3f}")
    print(f"  p-value = {pred_p:.3f}")

    plt.figure(figsize=(7, 6))
    sns.regplot(x=y, y=predicted_y)
    plt.xlabel(f"True {behavior_to_predict.replace('_', ' ')}")
    plt.ylabel(f"Predicted {behavior_to_predict.replace('_', ' ')}")
    plt.title(f"Prediction of '{behavior_to_predict}' from Brain-wide ID Pattern\n(r = {pred_r:.3f}, p = {pred_p:.3f})")
    plt.tight_layout()
    plot_path = os.path.join(OUTPUT_DIR, f"prediction_plot_{behavior_to_predict}.png")
    plt.savefig(plot_path, dpi=300)
    plt.close()
    print(f"Prediction plot saved to: {plot_path}")


def main():
    """
    Main function to load data and orchestrate the analyses.
    """
    if not os.path.exists(ID_RESULTS_CSV):
        print(f"FATAL ERROR: ID results file not found at {ID_RESULTS_CSV}"); return
        
    id_df = pd.read_csv(ID_RESULTS_CSV)
    id_df['Subject'] = id_df['Subject'].astype(str)
    
    subject_list = id_df['Subject'].unique()
    behavioral_data = [calculate_behavioral_metrics_for_subject(sub) for sub in subject_list]
    behavioral_df = pd.DataFrame([b for b in behavioral_data if b is not None])
    behavioral_df['Subject'] = behavioral_df['Subject'].astype(str)

    merged_df = pd.merge(id_df, behavioral_df, on="Subject")
    if merged_df.empty: print("Merging failed."); return
    print(f"Successfully created master dataframe for {merged_df['Subject'].nunique()} subjects.")
    
    run_comprehensive_correlations(merged_df)
    run_prediction_analysis(merged_df)
    
    print(f"\n\nAll analyses complete. Results are in the '{OUTPUT_DIR}' directory.")


if __name__ == '__main__':
    main()
